begin transaction read only;
select jsonb_build_object('captured_at',now(),'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'signature',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'body_md5_normalized',md5(replace(p.prosrc,E'\r\n',E'\n')),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'config',p.proconfig)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('handle_new_user','has_club_role','has_club_access','member_status_timeline_trigger_v1','set_updated_at')),'constraints',(select jsonb_agg(jsonb_build_object('table',c.conrelid::regclass::text,'name',c.conname,'type',c.contype,'definition',pg_get_constraintdef(c.oid))) from pg_constraint c where c.conrelid in ('public.clubs'::regclass,'public.profiles'::regclass,'public.club_memberships'::regclass)));
rollback;
